86: const network={transport:null,connected:false,snapshotVersion:0,remotePlayers:[],sharedWorld:null,sendCommand(command){if(!this.connected||!this.transport)return false;this.transport.send(JSON.stringify({playerId:identity.playerId,command}));return true},applySnapshot(snapshot){if(!snapshot||snapshot.version<=this.snapshotVersion)return false;this.snapshotVersion=snapshot.version;if(snapshot.player){hero.x=snapshot.player.x;hero.y=snapshot.player.y;hero.hp=snapshot.player.hp;hero.mp=snapshot.player.mp}if(Array.isArray(snapshot.players))this.remotePlayers=snapshot.players;if(snapshot.world)this.sharedWorld=snapshot.world;return true}};
