90: function saveGame(){try{const data={version:1,name:hero.name,race:hero.race,className:hero.className,attributes:hero.attributes,level:hero.level,xp:hero.xp,next:hero.next,gold:hero.gold,potions:hero.potions,hp:hero.hp,maxHp:hero.maxHp,mp:hero.mp,maxMp:hero.maxMp,x:hero.x,y:hero.y,kills,equipment:hero.equipment,items:hero.items};localStorage.setItem(SAVE_KEY,JSON.stringify(data))}catch(e){}}
91: function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;const data=JSON.parse(raw);if(!data||data.version!==1||!races[data.race]||!classes[data.className]||typeof data.name!=='string')return null;return data}catch(e){return null}}
92: function applySaved(data){hero.name=data.name.slice(0,18)||'Adventurer';hero.race=data.race;hero.className=data.className;hero.attributes=makeAttributes(data.race,data.className);hero.level=Math.max(1,Math.min(20,Number(data.level)||1));hero.xp=Math.max(0,Number(data.xp)||0);hero.next=Math.max(100,Number(data.next)||100);hero.gold=Math.max(0,Number(data.gold)||0);hero.potions=Math.max(0,Number(data.potions)||0);hero.maxHp=Math.max(1,Number(data.maxHp)||75+hero.attributes.constitution*3+(hero.level-1)*18);hero.hp=Math.min(hero.maxHp,Math.max(1,Number(data.hp)||hero.maxHp));hero.maxMp=Math.max(1,Number(data.maxMp)||25+hero.attributes.intelligence*2+hero.attributes.wisdom+(hero.level-1)*8);hero.mp=Math.min(hero.maxMp,Math.max(0,Number(data.mp)||hero.maxMp));hero.x=Math.max(2,Math.min(46,Number(data.x)||24));hero.y=Math.max(2,Math.min(46,Number(data.y)||25));hero.equipment=data.equipment&&data.equipment.weapon?data.equipment:{weapon:{name:'Rusty Sword',icon:'⚔',slot:'weapon',attack:0,defense:0}};hero.items=Array.isArray(data.items)?data.items.slice(0,24):[];kills=Math.max(0,Number(data.kills)||0);identity.displayName=hero.name}
93: function renderChoices(){document.querySelector('#raceChoices').innerHTML=Object.entries(races).map(([name,r])=>`<button class="choice-card${name===chosenRace?' selected':''}" data-race="${name}"><b>${name}</b><small>${r.trait}</small></button>`).join('');document.querySelector('#classChoices').innerHTML=Object.entries(classes).map(([name,c])=>`<button class="choice-card${name===chosenClass?' selected':''}" data-class="${name}"><b>${name}</b><small>${c.description}</small></button>`).join('');document.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{chosenRace=b.dataset.race;renderChoices()});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{chosenClass=b.dataset.class;renderChoices()});const attrs=makeAttributes(chosenRace,chosenClass);document.querySelector('#creationPreview').innerHTML=`<strong>${chosenRace} ${chosenClass}</strong><br>${races[chosenRace].trait}. ${classes[chosenClass].description}.<br>STR ${attrs.strength} · DEX ${attrs.dexterity} · INT ${attrs.intelligence} · CON ${attrs.constitution} · WIS ${attrs.wisdom}`}
94: function createCharacter(){const name=document.querySelector('#characterName').value.trim();if(name.length<2){document.querySelector('#creationError').textContent='Enter a name with at least 2 characters.';return}hero.name=name.slice(0,18);hero.race=chosenRace;hero.className=chosenClass;hero.attributes=makeAttributes(chosenRace,chosenClass);hero.maxHp=75+hero.attributes.constitution*3;hero.hp=hero.maxHp;hero.maxMp=25+hero.attributes.intelligence*2+hero.attributes.wisdom;hero.mp=hero.maxMp;identity.displayName=hero.name;Object.keys(keys).forEach(key=>keys[key]=false);joyEnd();document.querySelector('#creationScreen').classList.add('hidden');document.querySelector('#creationError').textContent='';syncCharacter();syncHud();saveGame();toast(`Welcome, ${hero.name}`,`${hero.race} ${hero.className} · Level 1`)}
