96: function syncCharacter(){document.querySelector('.hero-name').textContent=hero.name;document.querySelector('.level').innerHTML=`LEVEL <b id="level">${String(hero.level).padStart(2,'0')}</b> · ${hero.race.toUpperCase()} ${hero.className.toUpperCase()}`;const palette=races[hero.race];document.querySelector('.portrait').style.background=`linear-gradient(${palette.accent} 0 55%,#283a33 55%)`;document.querySelector('#skillBtn').innerHTML=`✦<br><small>${hero.className==='Warrior'?'POWER':hero.className==='Mage'?'SPELL':hero.className==='Archer'?'SHOT':'STRIKE'}</small>`;}
